export function writingTipHTML(t,target,esc){
 const link=key=>'#practice/'+encodeURIComponent(key)+'?from='+encodeURIComponent(target);
 return `<details class="revision-tip"><summary>${esc(t.title)}</summary><p><strong>Why here:</strong> ${esc(t.reason)}</p>${t.quote?`<blockquote class="short-quote">${esc(t.quote)}</blockquote>`:''}<p>${esc(t.rule)}</p><p class="tiny">${esc(t.watch)}</p><p><strong>Teaching pattern · adapt to your meaning:</strong> ${esc(t.pattern)}</p><p><strong>Example outside your field · ${esc(t.example.subject)}:</strong> ${esc(t.example.text)}</p><div class="actions"><a class="btn secondary" href="${link(t.practice_key)}">Practise and return to ${esc(target)}</a><a href="${link(t.warmup_key)}">Start with diagnosis</a><a href="${esc(t.reading.url)}" target="_blank" rel="noreferrer">Read the principle</a></div></details>`;
}
export async function mountWritingHelp({api,esc,host,node,paper,current}) {
 const directions=(paper.revision_decisions||[]).filter(d=>d.node_ids.includes(node.id));
 host.innerHTML=`<div class="wise-directions"><strong>Uploaded manuscript · find your earlier wording</strong><p>Choose an agreed manuscript passage, check its argument job, then keep it or make a small adaptation. The original file stays unchanged. Editing a copy opens a comparison with that source.</p><a class="btn secondary" href="#revision/${node.id}">Find and place existing passages</a>${directions.length?`<details><summary>${directions.length} discussion directions affect this target</summary>${directions.map(d=>`<p><strong>${esc(d.status==='confirmed'?'Confirmed by you':d.status.replaceAll('_',' '))}:</strong> ${esc(d.text)}</p>`).join('')}<a href="#revision">Review the discussion decisions</a></details>`:''}</div><details class="wise-target-support"><summary>Teaching hints · use only if you need help</summary><div id="wise-node-tips"><p class="tiny">Finding relevant language help…</p></div></details>`;
 const data=await api('/revision/support/'+encodeURIComponent(node.id));if(!current()||!host.isConnected)return;
 host.dataset.firstCheck=data.tips[0].reason;
 host.querySelector('.wise-directions').insertAdjacentHTML('beforeend',`<p><strong>Suggested check (teaching help):</strong> ${esc(data.tips[0].reason)}</p>`);
 host.querySelector('#wise-node-tips').innerHTML=`<p class="tiny">${esc(data.basis)}. ${esc(data.workflow)}</p>${data.tips.map(t=>writingTipHTML(t,node.id,esc)).join('')}${data.expanded_cards.length?'<h4>Expanded analysis for this argument</h4>':''}${data.expanded_cards.map(c=>`<p><a href="#revision/${node.id}?document=${c.document_id}&segment=${c.segment_id}">${esc(c.card_id)} · read the crosswalk and recommended adjustment</a></p>`).join('')}`;
}
